"""Fix a real bug the D-nn sweep introduced.

The sweep mapped every D-12 to PKG-FR-KEY-COPY (ADR-020's D-12), but ADR-014 has
its own D-12 for the unified --dry-run contract. Six sites cite the dry-run one and
now wrongly claim PKG-FR-KEY-COPY. Replace with ADR-014 (or drop the duplicate ref).
"""
import re

fixes = {
    'src/pcswitcher/orchestrator.py': [
        ('(dry-run mode \\()`PKG-FR-KEY-COPY`(: dry-run must)', r'\1`ADR-014`\2'),
        ('ADR-014/`PKG-FR-KEY-COPY`', 'ADR-014'),
    ],
    'tests/integration/test_dry_run.py': [
        ('\\(ADR-014, `PKG-FR-KEY-COPY`\\)', '(ADR-014)'),
        ('ADR-014 / `PKG-FR-KEY-COPY`', 'ADR-014'),
        ('\\(`PKG-FR-KEY-COPY`\\)\\.\\\\n', '(ADR-014).\\n'),
    ],
}
for f, subs in fixes.items():
    t = open(f).read()
    changed = False
    for pat, sub in subs:
        new = re.sub(pat, sub, t)
        if new != t:
            changed = True
            t = new
    if changed:
        open(f, 'w').write(t)
        print(f'changed: {f}')
    else:
        print(f'nochange: {f}')

